using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.TestManagement;using ProMaxx2.QA.Domain.TestManagement;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class TestCaseRepository(QaDbContext db):ITestCaseRepository
{
 public async Task<IReadOnlyList<TestCaseDto>>ListAsync(Guid?projectId,string?search,CancellationToken ct){var q=db.TestCases.AsNoTracking().Where(x=>!x.IsDeleted);if(projectId.HasValue)q=q.Where(x=>x.ProjectId==projectId);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.TestCaseCode.Contains(search)||x.Title.Contains(search));return await q.OrderBy(x=>x.TestCaseCode).Select(x=>new TestCaseDto(x.TestCaseId,x.ProjectId,x.ModuleId,x.TestCaseCode,x.Title,x.Objective,x.Preconditions,x.Priority,x.TestType,x.AutomationCandidate,x.Status,x.RevisionNo,x.OwnerUserId,x.Steps.Where(s=>s.RevisionNo==x.RevisionNo).OrderBy(s=>s.StepNo).Select(s=>new StepDto(s.StepNo,s.Action,s.TestDataText,s.ExpectedResult)).ToList())).ToListAsync(ct);}
 public async Task<TestCaseDto?>GetAsync(Guid id,CancellationToken ct)=>await db.TestCases.AsNoTracking().Where(x=>x.TestCaseId==id&&!x.IsDeleted).Select(x=>new TestCaseDto(x.TestCaseId,x.ProjectId,x.ModuleId,x.TestCaseCode,x.Title,x.Objective,x.Preconditions,x.Priority,x.TestType,x.AutomationCandidate,x.Status,x.RevisionNo,x.OwnerUserId,x.Steps.Where(s=>s.RevisionNo==x.RevisionNo).OrderBy(s=>s.StepNo).Select(s=>new StepDto(s.StepNo,s.Action,s.TestDataText,s.ExpectedResult)).ToList())).SingleOrDefaultAsync(ct);public Task<TestCase?>FindAsync(Guid id,CancellationToken ct)=>db.TestCases.Include(x=>x.Steps).SingleOrDefaultAsync(x=>x.TestCaseId==id&&!x.IsDeleted,ct);public Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct)=>db.TestCases.AnyAsync(x=>x.ProjectId==projectId&&x.TestCaseCode==code,ct);public Task AddAsync(TestCase e,CancellationToken ct)=>db.TestCases.AddAsync(e,ct).AsTask();
 public async Task LinkAsync(Guid reqId,Guid caseId,string?type,CancellationToken ct){if(!await db.Requirements.AnyAsync(x=>x.RequirementId==reqId&&!x.IsDeleted,ct)||!await db.TestCases.AnyAsync(x=>x.TestCaseId==caseId&&!x.IsDeleted,ct))throw new ProMaxx2.QA.Application.Projects.EntityNotFoundException("Requirement or test case not found.");if(!await db.RequirementTestCases.AnyAsync(x=>x.RequirementId==reqId&&x.TestCaseId==caseId,ct))await db.RequirementTestCases.AddAsync(new(reqId,caseId,type),ct);}public async Task UnlinkAsync(Guid reqId,Guid caseId,CancellationToken ct){var link=await db.RequirementTestCases.FindAsync([reqId,caseId],ct);if(link is not null)db.RequirementTestCases.Remove(link);}public async Task<IReadOnlyList<RtmRow>>RtmAsync(Guid releaseId,CancellationToken ct)=>await db.Requirements.AsNoTracking().Where(x=>x.ReleaseId==releaseId&&x.IsInScope&&!x.IsDeleted).OrderBy(x=>x.RequirementCode).Select(x=>new RtmRow(x.RequirementId,x.RequirementCode,x.Title,x.Priority,db.RequirementTestCases.Count(l=>l.RequirementId==x.RequirementId),db.RequirementTestCases.Any(l=>l.RequirementId==x.RequirementId)?"Covered":"Not Covered",x.Status)).ToListAsync(ct);public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
